widget.solution:
def iterate(T, x0, n):
    """[x0, T(x0), ..., T^n(x0)]."""
    xs = [x0]
    for _ in range(n):
        xs.append(T(xs[-1]))
    return xs

def apriori_steps(q, d01, tol):
    """Smallest n with q**n / (1 - q) * d01 < tol."""
    if q >= 1:
        raise ValueError("not a contraction")
    n = 0
    while q ** n / (1 - q) * d01 >= tol:
        n += 1
    return n
